import React from "react";
import HorizontalButtonCard, { HorizontalClickableCardProps } from "../horizontalclickablecard/HorizontalClickableCard";
import VerticalButtonCard, { VerticalClickableCardProps } from "../verticalclickablecard/VerticalClickableCard";

export type ClickableCardProps = (HorizontalClickableCardProps & VerticalClickableCardProps) & {
  horizontal: boolean;
};

const ClickableCard: React.FC<ClickableCardProps> = ({ horizontal, ...props }) => {
  return horizontal ? (
    <HorizontalButtonCard {...props} />
  ) : (
    <VerticalButtonCard {...props} />
  );
};

export default ClickableCard;